private void gameInfo(byte[] payload) throws IOException {
    Protocol.LitoGameInfoRequest request = Protocol.litoGameInfoRequest(payload);
    System.out.println("[LiTo] C_LITO_GAME_INFO request=" + request
            + " plain=" + Protocol.hex(payload));
    if (phase != Phase.ROOM || currentRoomId == 0) {
        System.out.println("[LiTo] C_LITO_GAME_INFO ignored invalid-phase=" + phase);
        return;
    }
    if (rentalTownRoomState) {
        handleRentalTownGameInfo(request);
        return;
    }
    if (request instanceof Protocol.LitoModeStepRequest modeStep) {
        changeRoomMode(modeStep.direction());
    } else if (request instanceof Protocol.LitoMapSelectionRequest mapSelection) {
        changeRoomMap(mapSelection.mapId());
    } else {
        throw new IllegalStateException("unknown native C_D1 request " + request);
    }
}

private void sendGameInfoSnapshot() throws IOException {
    // Native S_D5 splits room state across two records. Subtype 0 carries
    // the room summary/mode/map/owner; subtype 1 carries the editable
    // password, attributes, capacity, four options and selection list.
    GameHub.RoomSettings settings = hub.roomSettings(currentRoomId);
    int mapId = hub.roomRules(currentRoomId).mapId();
    String owner = hub.roomOwnerDisplayName(currentRoomId);
    sendEncrypted(Protocol.litoRoomSummary(currentRoomId, settings, mapId, owner),
            "S_LITO_GAME_INFO summary subtype=0 owner=" + owner);
    sendEncrypted(Protocol.litoRoomConfiguration(currentRoomId, settings),
            "S_LITO_GAME_INFO configuration subtype=1");
}

private void changeRoomMode(Protocol.LitoModeStepDirection direction) throws IOException {
    GameHub.RoomSettings current = hub.roomSettings(currentRoomId);
    BattleRules.Mode previousMode = BattleRules.Mode.fromWire(
            current.option0() & 0x7F);
    if (!previousMode.isBattleScene()) {
        // Native type 6 is a server-gated town scene.  The exact C_D1
        // request carries only a direction, so there is no evidence for
        // interpreting an ordinary room-mode click as a transition out
        // of that special state.  Preserve the authoritative snapshot.
        sendGameInfoSnapshot();
        return;
    }
    BattleRules.Mode mode = BattleRules.Mode.stepNative(current.option0() & 0x7F, direction);
    GameHub.RoomSettings replacement = new GameHub.RoomSettings(
            current.name(), current.password(), current.capacity(),
            mode.teamBased()
                    ? current.attributes() | GameHub.RoomSettings.EQUAL_SIDES
                    : current.attributes() & ~GameHub.RoomSettings.EQUAL_SIDES,
            mode.wireId(), current.option1(), current.option2(),
            current.option3(), current.option4(),
            current.selections());
    if (!hub.updateSettings(currentRoomId, this, replacement)) {
        sendGameInfoSnapshot();
        return;
    }

    resetRoomReadyAfterSettingsChange();
    byte[] modeChanged = Protocol.litoRoomMode(currentRoomId, mode);
    int mapId = BattleRules.decode(replacement).mapId();
    byte[] mapChanged = Protocol.litoRoomMap(currentRoomId, mapId);
    for (ClientSession member : hub.roomMembers(currentRoomId)) {
        member.sendEncrypted(modeChanged, "S_LITO_GAME_INFO mode=" + mode.wireId()
                + " name=" + mode.displayName());
        member.sendEncrypted(mapChanged, "S_LITO_GAME_INFO map=" + mapId + " mode-reset");
    }

private void resetRoomReadyAfterSettingsChange() throws IOException {
    List<ClientSession> members = hub.roomMembers(currentRoomId);
    for (ClientSession member : members) {
        if (!member.ready) continue;
        member.ready = false;
        byte[] changed = Protocol.readyState(member.litoDisplayName(), false);
        for (ClientSession recipient : members) {
            recipient.sendEncrypted(changed,
                    "S_LITO_READY_GAME reset player=" + member.playerName());
        }
    }
}

enum LitoModeStepDirection {
    NEXT(1),
    PREVIOUS(2);

    private final int wireValue;

    LitoModeStepDirection(int wireValue) {
        this.wireValue = wireValue;
    }

    int wireValue() {
        return wireValue;
    }

    static LitoModeStepDirection fromWire(int value) {
        return switch (value) {
            case 1 -> NEXT;
            case 2 -> PREVIOUS;
            default -> throw new IllegalArgumentException(
                    "invalid native C_D1 mode-step direction=" + value);
        };
    }
}

sealed interface LitoGameInfoRequest
        permits LitoModeStepRequest, LitoMapSelectionRequest {}

record LitoModeStepRequest(LitoModeStepDirection direction)
        implements LitoGameInfoRequest {
    LitoModeStepRequest {
        Objects.requireNonNull(direction, "LiTo mode-step direction");
    }
}

static LitoGameInfoRequest litoGameInfoRequest(byte[] payload) {
    Reader in = new Reader(payload);
    if (in.c() != C_LITO_GAME_INFO) {
        throw new IllegalArgumentException("not a native C_D1 game-info request");
    }
    int subtype = in.c();
    if (subtype == 2) {
        if (in.remaining() != 1) {
            throw new IllegalArgumentException("invalid native C_D1 mode-step length");
        }
        return new LitoModeStepRequest(LitoModeStepDirection.fromWire(in.c()));
    }
    if (subtype == 3) {
        if (in.remaining() != 2) {
            throw new IllegalArgumentException("invalid native C_D1 map length");
        }
        return new LitoMapSelectionRequest(in.h());
    }
    throw new IllegalArgumentException("unsupported native C_D1 subtype=" + subtype);
}

static Mode stepNative(int value, Protocol.LitoModeStepDirection direction) {
    if (value < 0 || value >= NATIVE_MODE_COUNT) {
        throw new IllegalArgumentException(
                "server-gated LiTo mode cannot use ordinary mode stepping");
    }
    // The native room arrows send only direction 1/2.  The original
    // product presentation order is Racing, Death, Honor, Quest,
    // Time, Siege, while the exact wire/category ids are
    // 0,1,5,2,4,3.  The server therefore owns this permutation.
    int[] presentationOrder = {0, 1, 5, 2, 4, 3};
    int position = -1;
    for (int index = 0; index < presentationOrder.length; index++) {
        if (presentationOrder[index] == value) {
            position = index;
            break;
        }
    }
    if (position < 0) throw new IllegalArgumentException("unknown native mode " + value);
    int delta = switch (direction) {
        case NEXT -> 1;
        case PREVIOUS -> -1;
    };
    return fromWire(presentationOrder[Math.floorMod(
            position + delta, presentationOrder.length)]);
}

synchronized boolean updateSettings(long roomId, ClientSession requester, RoomSettings settings) {
    Room room = rooms.get(roomId);
    if (room == null || room.owner != requester || room.battleStarted) return false;
    if (room.combatantCount() > nativeCombatantCapacity(settings)) return false;
    BattleRules.Mode previousMode = room.match.rules().mode();
    BattleRules.Mode nextMode = BattleRules.decode(
            settings, battleControls).mode();
    int nextMapId = previousMode == nextMode
            && nextMode.maps().contains(room.selectedMapId)
            ? room.selectedMapId : nextMode.maps().get(0);
    room.settings = settings;
    room.selectedMapId = nextMapId;
    room.ready.clear();
    room.match.reconfigure(BattleRules.decode(
            settings, nextMapId, battleControls));
    if (previousMode != BattleRules.Mode.SIEGE_WAR
            && nextMode == BattleRules.Mode.SIEGE_WAR) {
        balanceSiegeForces(room);
    }
    return true;
}
